{
  "items": [
    {
      "concept_name": {
        "text": "Neural network as a collection of specialized detectors (students) for image features",
        "refs": ["Q0005", "Q0006", "Q0009", "Q0012", "Q0013"],
        "claims": [
          {
            "text": "Each student (e.g., Mike, Mohan, Saqib) is assigned to detect a specific part of an animal's body (eyes, nose, ears) from an image.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0005", "Q0006", "Q0009", "Q0012"],
            "related_refs": []
          },
          {
            "text": "The detectors output a confidence score between 0 and 1 indicating how likely the feature is present.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0007", "Q0010", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Combining individual feature scores to decide if the whole face is present",
        "refs": ["Q0014", "Q0015", "Q0016", "Q0017", "Q0018"],
        "claims": [
          {
            "text": "Serena (the final classifier) uses the scores from the feature detectors to determine whether the image contains the animal's face.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "continuation",
            "refs": ["Q0014", "Q0015"],
            "related_refs": []
          },
          {
            "text": "Weight can be assigned to different features (e.g., more weight to face) when aggregating scores.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0017"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Training detectors by supervised learning",
        "refs": ["Q0008", "Q0019", "Q0020", "Q0021"],
        "claims": [
          {
            "text": "Students (detectors) are trained on labeled examples to recognize their assigned feature.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0008"],
            "related_refs": []
          },
          {
            "text": "Before training, detectors make random guesses; after training they produce meaningful confidence scores.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "continuation",
            "refs": ["Q0019", "Q0020", "Q0021"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Supervision provides correct answers to guide learning",
        "refs": ["Q0022", "Q0023"],
        "claims": [
          {
            "text": "A supervisor knows the correct answer and can provide feedback to the final classifier after it makes a decision.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0022", "Q0023"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Limitations of static pixel‑based rules for object detection",
        "refs": ["Q0003", "Q0004"],
        "claims": [
          {
            "text": "Static algorithms that check fixed pixel colors or positions fail because features can appear at different locations and scales.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "identified_mistake",
            "refs": ["Q0003", "Q0004"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Neural networks learn spatially invariant representations to overcome this limitation",
        "refs": ["Q0002"],
        "claims": [
          {
            "text": "The brain (and neural networks) can recognize patterns in parallel and irrespective of exact position, enabling robust object detection.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0002"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    }
  ],
  "abstentions": [],
  "excluded": []
}
